SELECT r.name AS division, SUM(COALESCE(o.total_bdt, o.total_amount * cr.bdt_per_unit)) AS gmv FROM orders o LEFT JOIN currency_rates cr ON cr.rate_date = CAST(o.order_at AS DATE) AND cr.currency = o.currency JOIN customer_addresses a ON a.address_id = o.address_id JOIN cities ci ON ci.city_id = a.city_id JOIN regions r ON r.region_id = ci.region_id WHERE o.status NOT IN ('cancelled', 'canceled', 'payment_failed') AND CAST(o.order_at AS DATE) BETWEEN DATE '2024-07-01' AND DATE '2024-09-30' GROUP BY r.name
